window.NPC_CHUNK_3 = [{"name":"Audbrey Aldamori, Vampire Aristocrat","cr":14,"xp":38400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":2},{"class":"fighter","level":11}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["augmented","human"],"templates_applied":"vampire","init":9,"senses":["darkvision 60 ft."],"ac":28,"ac_touch":18,"ac_flat_footed":22,"ac_mods":"+4 armor, +2 deflection, +5 Dex, +1 dodge, +6 natural","hp":145,"hd":"11d10+2d8+76","hd_value":13,"hp_mods":"fast healing 5","fort":11,"ref":10,"will":7,"save_mods":"+3 vs. fear","defensive_abilities":["channel resistance +4"],"dr":"10/magic and silver","immunities":["undead traits"],"resists":["cold 10","electricity 10"],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"+1 keen rapier +23 (1d6+11/15-20) or slam +19 (1d4+7 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"},{"type":"children of  the night"},{"type":"create spawn"},{"type":"dominate","details":"DC  20"},{"type":"energy drain","details":"2 levels, DC 20"}],"strength":22,"dexterity":20,"intelligence":15,"wisdom":12,"charisma":18,"baseatk":12,"cmb":18,"cmd":36,"feats":[{"feat":"Alertness","type":"bonus"},{"feat":"Bleeding Critical"},{"feat":"Blind-Fight"},{"feat":"Combat Reflexes","type":"bonus"},{"feat":"Critical Focus"},{"feat":"Dazzling Display"},{"feat":"Deadly Stroke"},{"feat":"Deceitful"},{"feat":"Dodge","type":"bonus"},{"feat":"Greater Weapon Focus (rapier)"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Lightning Reflexes","type":"bonus"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Shatter Defenses"},{"feat":"Spring Attack"},{"feat":"Step Up"},{"feat":"Toughness","type":"bonus"},{"feat":"Weapon Focus (rapier)"},{"feat":"Weapon Specialization (rapier)"}],"skills":[{"skill":"Bluff","value":29},{"skill":"Diplomacy","value":13},{"skill":"Disguise","value":13},{"skill":"Fly","value":9},{"skill":"Intimidate","value":17},{"skill":"Knowledge (nobility)","value":15},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":24},{"skill":"Survival","value":10}],"languages":["Common","Hallit"],"sq":["armor training +3","bravery +3","change  shape (dire bat or wolf, beast shape II)","gaseous form","shadowless","spider climb","weapon training (light blades +2,  natural +1)"],"special_abilities":[{"type":"Blood Drain","kind":"Su","details":"Audbrey can suck blood from a grappled opponent; if he establishes or maintains a pin, he drains blood, dealing 1d4 points of Constitution damage. Audbrey heals 5 hit points or gains 5 temporary hit points for 1 hour (up to a 145 temporary hit points) each round he drains blood."},{"type":"Change Shape","kind":"Su","details":"Audbrey can use change shape to assume the form of a dire bat or wolf, as beast shape II."},{"type":"Children of the Night","kind":"Su","details":"Once per day, Audbrey can call forth 1d6+1 rat swarms, 1d4+1 bat swarms, or 2d6 wolves. These creatures arrive in 2d6 rounds and serve him for up to 1 hour."},{"type":"Create Spawn","kind":"Su","details":"Audbrey can create spawn out of humanoids he slays with blood drain or energy drain. The victim rises from death as a vampire in 1d4 days. This vampire is under Audbrey's command and remains enslaved until its master's destruction. Audbrey may have enslaved spawn totaling no more than 26 Hit Dice; any spawn he creates that would exceed this limit become free-willed undead. Audbrey may free an enslaved spawn in order to enslave a new spawn, but once freed, a vampire or vampire spawn cannot be enslaved again."},{"type":"Dominate","kind":"Su","details":"Audbrey can crush a humanoid opponent's will as a standard action. Anyone he targets must succeed on a Will save or fall instantly under his influence, as though by a dominate person spell (caster level 12th). The ability has a range of 30 feet."},{"type":"Energy Drain","kind":"Su","details":"A creature hit by Audbrey's slam gains two negative levels. This ability only triggers once per round, regardless of the number of attacks Audbrey makes."},{"type":"Gaseous Form","kind":"Su","details":"As a standard action, Audbrey can assume gaseous form at will (caster level 5th), and can remain gaseous indefinitely, with a fly speed of 20 ft. and perfect maneuverability."},{"type":"Shadowless","kind":"Ex","details":"Audbrey casts no shadows and shows no reflection in a mirror."},{"type":"Spider Climb","kind":"Ex","details":"Audbrey can climb sheer surfaces as though under the effects of a spider climb spell."}],"gear":"mithral shirt, +1 keen rapier, cloak of elvenkind, belt of incredible dexterity +2, brooch of shielding (101 charges), ring of protection +2, potion of inflict moderate wounds (3), potion of nondetection","during_combat":"Audbrey first attacks spellcasters using energy drain and then uses dominate on melee targets.","morale":"Audbrey fights until forced into gaseous form.","source":"Classic Horrors"},{"name":"Gillamoor Plague Zombie","cr":1,"xp":400,"race":"human","age_category":"Adult","alignment":"NE","size":"Medium","type":"undead","sub_types":["human"],"templates_applied":"plague,relentless,brain-eating@zombie","init":2,"senses":["darkvision 60 ft.","scent"],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":22,"hd":"4d8+4","hd_value":4,"fort":1,"ref":3,"will":4,"immunities":["undead traits"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":40}],"melee":"slam +6 (1d6+3 plus grab), bite (1d6+3 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"brain-eating"},{"type":"create spawn"},{"type":"death burst"},{"type":"disease"},{"type":"grab"},{"type":"quick strikes"}],"strength":17,"dexterity":14,"wisdom":10,"charisma":10,"baseatk":3,"cmb":6,"cmd":18,"feats":[{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Climb","value":11},{"skill":"Survival","value":0,"special":"+4 when tracking by scent"}],"special_abilities":[{"type":"Brain-eating","kind":"Ex","details":"After killing a target, the zombie uses its next turn to eat it's victim's brain. This prevents raising the body from the dead by any method that requires an intact corpse."},{"type":"Create Spawn","kind":"Su","details":": Anyone killed after being bitten by a Gillamoor zombie rises as a Gillamoor zombie 2d6 hours later unless the corpse is blessed or similar measures are taken."},{"type":"Death Burst","kind":"Ex","details":"When the zombie dies, it explodes in a burst of decay. All creatures adjacent to the zombie are exposed to its disease as if struck by a slam attack and must make a Fortitude save or contract zombie rot."},{"type":"Disease","kind":"Su","details":"The zombie's natural attacks carry the zombie rot disease. Zombie rot: slam- injury; save Fort DC 12; onset 1d4 days; frequency 1/day; effect 1d2 Con, this damage cannot be healed while the creature is infected; cure 2 consecutive saves. Anyone who dies while infected rises as a Gillamoor zombie in 2d6 hours."},{"type":"Quick Strikes","kind":"Ex","details":"Whenever the zombie takes a full-round attack action, it can make one additional slam attack at its highest base attack bonus."}],"before_combat":"Gillamoor plague zombies shamble about like normal zombies, only using their full speed if attacked or if they are in charge range of an opponent.","during_combat":"A Gillamoor plague zombie focuses all of its attacks on a single opponent, attempting to bite and grab the victim to feed upon its brain. It pursues its chosen quarry until either the prey or the zombie is dead.","morale":"Gillamoor plague zombies fight until destroyed.","source":"Classic Horrors"},{"name":"Jam us Hainard","cr":6,"xp":2400,"race":"halfling","gender":"Male","age_category":"Adult","classes":[{"class":"paladin of Erastil","level":6}],"alignment":"LG","size":"Small","type":"humanoid","sub_types":["halfling"],"init":0,"auras":["courage (+4 morale bonus to saves vs. fear)","good"],"ac":22,"ac_touch":11,"ac_flat_footed":22,"ac_mods":"+9 armor, +2 shield, +1 size","hp":45,"hd":"6d10+12","hd_value":6,"fort":10,"ref":6,"will":9,"defensive_abilities":["divine grace","divine health","fearless"],"immunities":["disease","fear"],"speed":[{"type":"land","speed":15}],"melee":"lance +11 (1d6+2/x3) or longsword +9 (1d6+2/19-20)","ranged":"cold iron javelin +7 (1d4+2)","space":"5 ft.","reach":"5 ft., 10 ft. with lance","special_attacks":[{"type":"channel positive energy","details":"3d6, DC 16"},{"type":"smite evil","details":"2/day"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect evil"}]}],"spellsprepared_caster_level":3,"spellsprepared_concentration":6,"spellsprepared":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"lesser restoration"},{"spell":"protection from evil"}]}],"strength":14,"dexterity":10,"constitution":12,"intelligence":13,"wisdom":10,"charisma":16,"baseatk":6,"cmb":7,"cmd":17,"feats":[{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (lance)"}],"skills":[{"skill":"Climb","value":3},{"skill":"Diplomacy","value":8},{"skill":"Handle Animal","value":9},{"skill":"Heal","value":5},{"skill":"Knowledge (religion)","value":6},{"skill":"Perception","value":6},{"skill":"Ride","value":3},{"skill":"Sense Motive","value":5},{"skill":"Spellcraft","value":5}],"languages":["Common","Halfling"],"sq":["channel positive energy (3d6)","lay on hands (6/day, 3d6)","mercy  (dazed, shaken)"],"gear":"masterwork full plate, masterwork heavy wooden shield, masterwork lance, 5 cold iron javelins, longsword, riding dog (Booke) with leather barding, 413 gp, wand of cure light wounds (30 charges)","before_combat":"If facing undead or numerous evil adversaries, Jamus uses protection from evil. Jamus usually has his trained riding dog (Booke) with him as a guard animal and mount.","during_combat":"Jamus prefers to fight while mounted, riding Booke in everyday situations but summoning Sorrell when going into dangerous territory. Jamus typically uses Power Attack on a lance charge (+13, 2d6+4). If dismounted or unable to maneuver while riding, he switches to his longsword.","morale":"Jamus never flees while his allies are in danger, and harries foes to allow allies to retreat.","source":"Andoran"},{"name":"Jarvis Alebrecht","cr":6,"xp":2400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"expert","level":5},{"class":"fighter","level":4}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+5 armor, +2 Dex","hp":52,"hd":"4d10+5d8+4","hd_value":9,"fort":6,"ref":5,"will":8,"save_mods":"+1 vs. fear","speed":[{"type":"land","speed":30}],"melee":"mwk short sword +9/4 (1d6+1/19-20)","ranged":"mwk sling +10 (1d4)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":15,"constitution":10,"intelligence":13,"wisdom":10,"charisma":16,"baseatk":7,"cmb":8,"cmd":20,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Persuasive"},{"feat":"Quick Draw"},{"feat":"Skill Focus (Intimidate)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Diplomacy","value":13},{"skill":"Disguise","value":15},{"skill":"Heal","value":8},{"skill":"Intimidate","value":21},{"skill":"Knowledge (local)","value":9},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":11}],"languages":["Common","Infernal"],"sq":["armor training +1","bravery +1"],"gear":"+2 studded leather armor, cloak of resistance +1, masterwork short sword, masterwork sling, 20 sling bullets, 82 pp, potion of cure moderate wounds (3), potion of eagle's splendor","during_combat":"Jarvis tends to hang back in battle and use his sling at a distance if possible. In melee, he teams up with an ally to gain flanking attacks and prevent the same.","morale":"Jarvis is no coward, but he is also not a front-line fighter. He defends himself and his allies to the best of his abilities but will not make foolhardy moves.","source":"AP 29"},{"name":"Maglin, Council Hushman","cr":9,"xp":6400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"assassin","level":3},{"class":"rogue","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":20,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+4 armor, +1 deflection, +3 Dex, +2 shield","hp":54,"hd":"7d8+3d8+10","hd_value":10,"fort":4,"ref":10,"will":2,"save_mods":"+1 vs. poison","defensive_abilities":["evasion","improved uncanny dodge","trap sense +2"],"speed":[{"type":"land","speed":30}],"melee":"mwk rapier +9 (1d6+2/18-20)","ranged":"mwk light crossbow +10 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleeding sneak attack  +6d6 plus 6 bleed"},{"type":"death attack","details":"DC  14"},{"type":"surprise attack"}],"strength":14,"dexterity":17,"constitution":12,"intelligence":13,"wisdom":8,"charisma":10,"baseatk":6,"cmb":8,"cmd":22,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Feint"},{"feat":"Improved Initiative"},{"feat":"Improved Trip"},{"feat":"Rapid Reload"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Bluff","value":13},{"skill":"Climb","value":12},{"skill":"Diplomacy","value":10},{"skill":"Disable Device","value":13},{"skill":"Disguise","value":13},{"skill":"Heal","value":6},{"skill":"Intimidate","value":13},{"skill":"Perception","value":12},{"skill":"Sleight of Hand","value":13},{"skill":"Stealth","value":16}],"languages":["Common","Infernal"],"sq":["poison use","rogue talents (bleeding attack, combat trick,  surprise attack)","trapfinding"],"gear":"+2 leather armor, +1 buckler, masterwork rapier, masterwork light crossbow with 10 bolts (each poisoned with blue whinnis), ring of protection +1, thieves' tools, quieting needles, pouch with 6 diamonds (200 gp each)","during_combat":"Maglin attempts to flank foes, making trip attacks on his second attacks until Kruthe manages to pin someone in a grapple, at which point he focuses his sneak attacks on that target.","morale":"Maglin fights to the death, believing he has reinforcements on the way. He tumbles behind his minions and makes ranged attacks if reduced below 20 hp.","source":"AP 29"},{"name":"Kruthe The Hammer","cr":7,"xp":3200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":8}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["giant","human"],"templates_applied":"ogrekin","init":1,"senses":["low-light vision"],"ac":22,"ac_touch":11,"ac_flat_footed":21,"ac_mods":"+8 armor, +1 Dex, +3 natural","hp":112,"hd":"8d10+64","hd_value":8,"fort":12,"ref":3,"will":3,"save_mods":"+2 vs. fear","speed":[{"type":"land","speed":30}],"melee":"+1 warhammer +17 (1d8+9/19- 20/x3), claw +13 (1d8+5)","space":"5 ft.","reach":"5 ft.","strength":21,"dexterity":12,"constitution":22,"intelligence":8,"wisdom":13,"charisma":6,"baseatk":8,"cmb":13,"cmd":24,"feats":[{"feat":"Greater Weapon Focus (warhammer)"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (warhammer)"},{"feat":"Power Attack"},{"feat":"Throw Anything"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (warhammer)"},{"feat":"Weapon Specialization (warhammer)"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Survival","value":12}],"languages":["Common"],"sq":["armor training +2","bravery +2","deformed","weapon training (hammers +1)"],"special_abilities":[{"type":"Deformed","kind":"Ex","details":"Like all ogrekin, Kruthe is deformed. His right wrist ends in an ugly, fleshy lump of cartilage and bone from which protrude two hook-like spurs, giving his hand the appearance of a claw hammer. This hand cannot wield weapons or shields, but the misshapen club grants him a natural weapon that deals 1d8 points of bludgeoning and piercing damage on a successful hit. Kruthe gains a +2 bonus on attempts to grapple, trip, and disarm foes with this claw."}],"gear":"+2 spiked banded mail; +1 warhammer; shrunken head pouch with 13 gp, 25 sp, and a cracked ruby worth 800 gp, potion of cure serious wounds (2)","during_combat":"Kruthe is loud and unimaginative but still deadly in combat, prone to calling out his targets as he attacks them with crude and simpleminded threats, like \"Die you dumb metal person!\" when fighting an armored warrior, or \"You go squish now on Kruthe's hammer, little girly!\" when facing an unarmored sorcerer.","morale":"Kruthe sees this battle as another chance to impress Chammady, and fights to the death as a result.","source":"AP 29, Pathfinder Adventure Path volume #3 90"},{"name":"Thief","cr":3,"xp":800,"race":"human","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":8,"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 armor, +4 Dex, +1 dodge","hp":29,"hd":"4d8+8","hd_value":4,"fort":3,"ref":8,"will":0,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"mwk rapier +9 (1d6+1/18-20)","ranged":"mwk hand crossbow +8 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":13,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":8,"charisma":12,"baseatk":3,"cmb":4,"cmd":19,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Appraise","value":7},{"skill":"Bluff","value":8},{"skill":"Climb","value":8},{"skill":"Disable Device","value":11},{"skill":"Intimidate","value":8},{"skill":"Knowledge (local)","value":7},{"skill":"Perception","value":8},{"skill":"Sleight of Hand","value":11},{"skill":"Stealth","value":11}],"languages":["Common"],"sq":["trapfinding"],"gear":"+1 leather armor, masterwork rapier, masterwork hand crossbow with 10 bolts, stolen coins and jewelry worth 300 gp, potion of cure moderate wounds","during_combat":"These eager thieves work together to set up flanking attacks against foes, ganging up against single targets unless following specific orders to the contrary from Maglin.","morale":"As long as Maglin survives, these thieves fight to the death. If Maglin is defeated, these thieves flee if brought below 10 hit points (or immediately once three of them are defeated).","source":"AP 29"},{"name":"Dog's Tongue","cr":6,"xp":2400,"race":"redcap","gender":"Male","age_category":"Adult","alignment":"NE","size":"Small","type":"fey","init":8,"senses":["low-light vision"],"ac":20,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+2 armor, +4 Dex, +3 natural, +1 size","hp":60,"hd":"8d6+32","hd_value":8,"hp_mods":"fast healing 3","fort":6,"ref":10,"will":7,"dr":"10/cold iron","weaknesses":["irreligious"],"speed":[{"type":"land","speed":60}],"melee":"+1 scythe +11 (2d4+7/x4), kick +4 (1d4+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"boot stomp"}],"strength":18,"dexterity":19,"constitution":18,"intelligence":16,"wisdom":13,"charisma":15,"baseatk":4,"cmb":7,"cmd":21,"feats":[{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (scythe)"}],"skills":[{"skill":"Acrobatics","value":15,"special":"+12 jump"},{"skill":"Bluff","value":13},{"skill":"Climb","value":15},{"skill":"Escape Artist","value":15},{"skill":"Fly","value":0},{"skill":"Intimidate","value":10},{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":19}],"languages":["Common","Aklo","Giant"],"sq":["heavy weapons","red cap"],"special_abilities":[{"type":"Boot Stomp","kind":"Ex","details":"A redcap wears heavy iron boots with spiked soles that it uses to deadly effect in combat. These boots give the redcap a kick attack that it can make as a secondary attack, either as part of a full attack action or as part of its movement just as if it had the Spring Attack feat."},{"type":"Heavy Weapons","kind":"Ex","details":"A redcap's powerful hands and arms allow it to wield Medium weapons without penalty."},{"type":"Irreligious","kind":"Ex","details":"Bitter and blasphemous, a redcap cannot stand the symbols of goodaligned religions. If a foe spends a standard action presenting such a holy symbol, any redcap that can see that character must make a DC 15 Will save or become frightened for 1 minute and attempt to flee. A redcap who successfully saves merely becomes shaken for 1 minute."},{"type":"Red Cap","kind":"Su","details":"A redcap wears a tiny, shapeless woolen hat, dyed over and over with the blood of its victims. While wearing this cap, a redcap gains a +4 bonus on damage rolls and fast healing 3. These benefits are lost if the cap is removed or destroyed, and caps are not transferable, even between redcaps. A redcap can create a new cap to replace a lost cap with 10 minutes of work, although until the redcap takes a standard action to dip the cap in the blood of a foe the redcap helped to kill, it doesn't grant its bonuses."}],"gear":"leather armor, +1 Medium scythe, potion of water walk","during_combat":"Dog's Tongue moves in to strike the closest thief in melee, shrieking obscenities and challenges in high-pitched Aklo and clomping loudly across rooftops with his iron boots until all the thieves are slain, taking time to dip his red cap in the blood of anyone he helps to murder.","morale":"Dog's Tongue flees back to the Mother of Flies if brought below 15 hit points or if the PCs attack him.","source":"AP 29, Pathfinder Adventure Path volume #4 80"},{"name":"Madjaw","cr":10,"xp":9600,"race":"satyr","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":6}],"alignment":"CN","size":"Medium","type":"fey","init":3,"senses":["low-light vision"],"ac":21,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+4 armor, +3 Dex, +1 dodge, +5 natural, -2 rage","hp":178,"hd":"8d6+6d12+118","hd_value":14,"fort":15,"ref":11,"will":14,"defensive_abilities":["improved uncanny dodge","improved uncanny dodge","trap sense +2","trap sense +2"],"dr":"5/cold iron","speed":[{"type":"land","speed":30}],"melee":"+1 gnomebane greataxe +20 (1d12+13/19-20/x3), gore +18 (1d6+8), bite +13 (1d4+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pipes"},{"type":"rage","details":"20 rounds per day"},{"type":"rage powers","details":"animal fury, quick reflexes, renewed vigor [1d8+8 hp]"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm person"},{"spell":"dancing lights"},{"spell":"ghost sound"},{"spell":"sleep"},{"spell":"suggestion"}]},{"frequency":"1/day","spells":[{"spell":"fear"},{"spell":"summon nature's ally III"}]}],"strength":27,"dexterity":17,"constitution":26,"intelligence":10,"wisdom":14,"charisma":20,"baseatk":10,"cmb":16,"cmd":28,"feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Improved Critical (greataxe)"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greataxe)"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Climb","value":14},{"skill":"Intimidate","value":22},{"skill":"Perception","value":23},{"skill":"Perform (Wind)","value":20},{"skill":"Stealth","value":21},{"skill":"Survival","value":13}],"languages":["Common","Sylvan"],"gear":"hide armor, +1 gnomebane greataxe","during_combat":"Madjaw's hatred of humanoids is particularly strong when it comes to gnomes-he attacks them in preference to any other target. He rages immediately upon starting combat, and unless he's missing foes with his attacks he uses Power Attack to make his blows particularly ruinous. He generally doesn't use his spell-like abilities except when hard-pressed against foes who avoid melee.","morale":"Madjaw fights to the death.","base_statistics":"AC 23, touch 14, flat-footed 19; hp 150; Fort +13, Will +12; Melee +1 gnomebane greataxe +18 (1d12+10/19-20/x3), gore +18 (1d6+6), bite +13 (1d4+3); Str 23, Con 22","source":"AP 29, Pathfinder RPG Bestiary 241"},{"name":"Jinkin","cr":1,"xp":400,"race":"Jinkin","age_category":"Adult","alignment":"CE","size":"Tiny","type":"fey","init":4,"senses":["darkvision 120 ft.","low-light vision"],"ac":19,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+4 Dex, +1 dodge, +2 natural, +2 size","hp":3,"hd":"1d6","hd_value":1,"fort":0,"ref":6,"will":4,"dr":"5/cold iron","sr":16,"speed":[{"type":"land","speed":40}],"melee":"short sword +6 (1d3-4/19-20), bite +6 (1d2-4)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"},{"type":"tinkering"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"prestidigitation"}]},{"frequency":"1/day","spells":[{"spell":"dimension door"}]}],"strength":3,"dexterity":18,"constitution":11,"intelligence":14,"wisdom":14,"charisma":15,"baseatk":0,"cmb":2,"cmd":9,"feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":8,"special":"+4 jump"},{"skill":"Bluff","value":6},{"skill":"Climb","value":0},{"skill":"Craft (trapmaking)","value":6},{"skill":"Disable Device","value":5},{"skill":"Escape Artist","value":8},{"skill":"Fly","value":0},{"skill":"Perception","value":6},{"skill":"Stealth","value":16}],"languages":["Terran"],"special_abilities":[{"type":"Tinkering","kind":"Su","details":"A group of 6 jinkins, working together over the course of an hour, can create an effect identical to bestow curse (CL 6th; target must either be willing or helpless). The save DC is set by the jinkin with the highest Charisma score, and is equal to 14 plus that Charisma modifier (DC 16 for most groups of jinkins). Alternatively, the six jinkins can attempt to infuse a magic item with a curse-the nature of the curse is determined randomly. Half the time the curse simply makes the magic item unreliable so that there's a 20% chance each time it's used that it simply doesn't work, but the remainder of the time the curse creates a randomly determined drawback. A jinkin can take part in a tinkering only once per day, and may only tinker with a creature or object that isn't already cursed. Once a tinkering curse is in place, it is permanent until removed."}],"during_combat":"The jinkins rely on flanking PCs (with each other or the Deathgorger) so they can make sneak attacks in combat. If the PCs have used compost on themselves, the canny jinkins can use prestidigitation to clean the filth off of the PCs. (A PC can resist this unusual use of prestidigitation by making a DC 12 Reflex save-and swift-thinking PCs can use this tactic against the jinkins in return!)","morale":"A wounded jinkin immediately flees from the cave and into the surrounding wilds.","source":"AP 29, Pathfinder Adventure Path volume #19, page 82"},{"name":"Fmughwa The Deathgorger","cr":10,"xp":9600,"race":"giant bombardier beetle","age_category":"Adult","alignment":"N","size":"Gargantuan","type":"vermin","templates_applied":"advanced","init":0,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":6,"ac_flat_footed":21,"ac_mods":"+15 natural, -4 size","hp":147,"hd":"14d8+84","hd_value":14,"fort":15,"ref":4,"will":4,"immunities":["mind-affecting effects"],"speed":[{"type":"fly","speed":20,"maneuverability":"poor"},{"type":"land","speed":20}],"melee":"bite +18 (6d6+18)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"spray acid"},{"type":"trample","details":"2d6+18, DC 29"}],"strength":35,"dexterity":10,"constitution":23,"wisdom":10,"charisma":9,"baseatk":10,"cmb":26,"cmd":36,"cmd_special":"44 vs. trip","skills":[{"skill":"Fly","value":-10}],"special_abilities":[{"type":"Spray Acid","kind":"Ex","details":"Once per round as a standard action, Fmughwa can spray a 40-foot cone of acid. Those in this area take 4d6+8 points of acid damage (DC 23 Reflex save negates)."}],"during_combat":"Fmughwa mindlessly attacks the closest living target, ignoring only creatures that have taken the time to coat themselves with special compost.","morale":"Fmughwa fights to the death.","source":"AP 29, Pathfinder RPG Bestiary 33"},{"name":"Gryph","cr":1,"xp":400,"race":"Gryph","age_category":"Adult","alignment":"NE","size":"Small","type":"magical beast","init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size","hp":15,"hd":"2d10+4","hd_value":2,"fort":5,"ref":5,"will":1,"speed":[{"type":"fly","speed":50,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"bite +5 (1d6/x3), legs +5 (attach)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"implant eggs"}],"strength":11,"dexterity":15,"constitution":14,"intelligence":2,"wisdom":12,"charisma":7,"baseatk":2,"cmb":1,"cmd":13,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":5},{"skill":"Stealth","value":10}],"special_abilities":[{"type":"Attach","kind":"Ex","details":"When a gryph hits with its legs, its six talons latch tightly onto the target, anchoring it in place. An attached gryph is effectively grappling its prey. The gryph loses its Dexterity bonus to AC and has an AC of 11, but holds on with great tenacity and gains a +4 bonus on attack rolls with its bite. Alternatively, an attached gryph can attempt to implant eggs in the target. An attached gryph has a +8 racial bonus to maintain its grapple on a foe once it is attached. An attached gryph can be struck with a weapon or grappled itself-if its prey manages to win a grapple check or Escape Artist check against it, the gryph is removed."},{"type":"Implant Eggs","kind":"Ex","details":"Once per day, a gryph can implant eggs into a helpless target or a target that it is currently attached to as a full-round action by extending an ovipositor from its abdomen and penetrating the victim's flesh by making a successful +4 melee attack. On a hit, the ovipositor inflicts 1 damage and implants 1d4 eggs into the victim's body. As long as a victim has gryph eggs implanted in his body, he is sickened as the eggs draw nutrients from his blood and flesh. The eggs grow swiftly, hatching in a mere 1d4 minutes into ravenous baby gryphs that immediately burrow out of the victim's body. This inflicts 2 points of Constitution damage per baby gryph, after which the hatchlings immediately take wing and fly away. Treat a gryph hatchling as a bat if statistics are needed. Gryph eggs can be cut out of a victim's body with a successful DC 20 Heal check made as a full-round action that inflicts 1 point of damage per attempt. Although immunity to disease offers no special protection against gryph egg implantation, remove disease or heal immediately destroys any implanted gryph eggs."}],"during_combat":"A gryph tries to attach itself to a foe to lay its eggs, then flees once it does so.","morale":"A wounded gryph immediately flees back to its nest up in the Maggot Tree-if confronted there, it fights to the death.","source":"AP 29, Tome of Horrors Revised 230"},{"name":"Dark Creeper Footpad","cr":4,"xp":1200,"race":"Dark creeper","age_category":"Adult","classes":[{"class":"rogue","level":2}],"alignment":"CN","size":"Small","type":"humanoid","sub_types":["dark folk"],"init":9,"senses":["see in darkness"],"ac":18,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+2 armor, +5 Dex, +1 size","hp":44,"hd":"3d8+2d8+22","hd_value":5,"fort":5,"ref":9,"will":2,"defensive_abilities":["evasion"],"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +7 (1d3+2/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"detect magic"}]}],"strength":14,"dexterity":21,"constitution":18,"intelligence":8,"wisdom":12,"charisma":6,"baseatk":3,"cmb":4,"cmd":19,"feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":14},{"skill":"Fly","value":0},{"skill":"Linguistics","value":4},{"skill":"Perception","value":13},{"skill":"Stealth","value":24}],"languages":["Common","Dark Folk","Infernal"],"sq":["poison use","rag armor","rogue talent (fast stealth)","trapfinding"],"gear":"rag armor, masterwork dagger, black smear (5 doses)","during_combat":"The dark creepers create darkness when trying to make sneak attacks, flanking foes when they can't and following the orders of their dark stalker commanders as necessary.","morale":"They fight to the death as long as any dark stalkers live- otherwise they flee if reduced to less than 10 hit points.","source":"AP 29, Pathfinder RPG Bestiary 53"},{"name":"Dark Stalker Guildsman","cr":8,"xp":4800,"race":"Dark stalker","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["dark folk"],"init":7,"senses":["see in darkness"],"ac":24,"ac_touch":17,"ac_flat_footed":17,"ac_mods":"+4 armor, +7 Dex, +2 natural, +1 shield","hp":89,"hd":"6d8+4d8+44","hd_value":10,"fort":7,"ref":13,"will":2,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +10 (1d6+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleeding sneak attack +5d6 plus  5 bleed"},{"type":"death throes"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"detect magic"},{"spell":"fog cloud"}]}],"strength":16,"dexterity":24,"constitution":18,"intelligence":8,"wisdom":8,"charisma":15,"baseatk":7,"cmb":10,"cmd":27,"feats":[{"feat":"Double Slice"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Two- Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Climb","value":20},{"skill":"Linguistics","value":4},{"skill":"Perception","value":16},{"skill":"Stealth","value":24}],"languages":["Common","Dark Folk","Infernal"],"sq":["poison use","rogue talents (bleeding attack, finesse rogue)","trapfinding"],"gear":"+2 leather armor, 2 masterwork short swords, black smear (5 doses)","during_combat":"The dark stalkers create darkness in battle, attempting to sneak attack their opponents. They bellow orders and curses in Dark Folk at their underlings the entire time, directing them to set up flanking attacks.","morale":"These dark stalkers fight to the death as long as Stiglor lives. If he falls, they immediately retreat, covering their escape with a fog cloud. They hope to flee all the way to Walcourt, and canny PCs can follow them right up to the guildhall.","source":"AP 29, Pathfinder RPG Bestiary 54"},{"name":"Stiglor","cr":9,"xp":6400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":10}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":24,"ac_touch":12,"ac_flat_footed":22,"ac_mods":"+7 armor, +2 Dex, +4 natural, +1 shield","hp":105,"hd":"10d10+50","hd_value":10,"fort":11,"ref":9,"will":4,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":40}],"melee":"+1 cold iron battleaxe +11 (1d8+4/19-20/x3)","ranged":"mwk composite longbow +12 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"fey +4, elf +4, gnome +2"},{"type":"hunter's  bond","details":"hunting companions"}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":7,"spellsprepared_concentration":8,"spellsprepared":[{"spell_level":2,"spell_slots":1,"spells":[{"spell":"barkskin"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"alarm"},{"spell":"animal messenger"},{"spell":"longstrider"}]}],"strength":16,"dexterity":14,"constitution":18,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":10,"cmb":13,"cmd":25,"feats":[{"feat":"Diehard"},{"feat":"Double Slice"},{"feat":"Endurance"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative"},{"feat":"Improved Two- Weapon Fighting"},{"feat":"Two- Weapon Fighting"},{"feat":"Two-Weapon Defense"},{"feat":"Two-Weapon Rend"},{"feat":"Weapon Focus (battleaxe)"}],"skills":[{"skill":"Climb","value":13},{"skill":"Handle Animal","value":12},{"skill":"Intimidate","value":12},{"skill":"Knowledge (geography)","value":13},{"skill":"Perception","value":14},{"skill":"Stealth","value":12},{"skill":"Survival","value":14}],"languages":["Common"],"sq":["favored terrain (forest +4, urban  +2)","swift tracker","track","wild  empathy +9","woodland stride"],"gear":"+1 breastplate, +1 cold iron battleaxe (2), masterwork composite longbow (+3 Str) with 20 cold iron arrows, belt of mighty constitution +2, key to chest in area D17, potion of cure moderate wounds (2)","before_combat":"Stiglor casts an audible alarm on his tent every night. Before combat he casts barkskin and longstrider on himself.","during_combat":"Stiglor prefers to enter melee combat wielding his two battleaxes and attempting to make Two-Weapon Rend attacks on a single opponent. He pauses to use his healing magic when necessary, behind the cover of his underlings.","morale":"If reduced to 30 hp, Stiglor retreats to take pot shots with his bow from a position of cover. If reduced below 0 hp, he retreats into the forest, not to be seen again in this adventure (after all, he'll need to hide not only from the PCs, but from the Council's new leaders as well).","base_statistics":"AC 20, touch 12, flat-footed 18; Speed 30 ft.","source":"AP 29"},{"name":"Mother of Flies","cr":14,"xp":38400,"race":"green hag","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":14}],"alignment":"NE","size":"Medium","type":"monstrous humanoid","init":2,"senses":["darkvision 90 ft."],"ac":30,"ac_touch":14,"ac_flat_footed":30,"ac_mods":"+4 armor, +2 deflection, +2 Dex, +8 natural, +4 shield","hp":190,"hd":"9d10+14d6+92","hd_value":23,"fort":12,"ref":12,"will":17,"immunities":["disease","nausea","sickness"],"sr":16,"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"2 claws +22 (1d4+5/19-20 plus weakness)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"},{"spell":"tongues"},{"spell":"water breathing"}]},{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"disguise self"},{"spell":"ghost sound"},{"spell":"invisibility"},{"spell":"pyrotechnics"},{"spell":"tree shape"},{"spell":"whispering wind"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":14,"spellsknown_concentration":21,"spellsknown":[{"spell_level":7,"spell_slots":4,"spells":[{"spell":"insanity"},{"spell":"plant shape III"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"eyebite"},{"spell":"flesh to stone"},{"spell":"shadow walk"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"baleful polymorph"},{"spell":"contact other plane"},{"spell":"insect plague"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"bestow curse"},{"spell":"dimension door"},{"spell":"phantasmal killer"},{"spell":"repel vermin"},{"spell":"scrying"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"contagion"},{"spell":"dispel magic"},{"spell":"fly"},{"spell":"nondetection"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"acid arrow"},{"spell":"cat's grace"},{"spell":"detect thoughts"},{"spell":"hideous laughter"},{"spell":"summon swarm"},{"spell":"web"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"charm animal"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"obscuring mist"},{"spell":"shield"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"bloodline":"arcana, mimicry","strength":20,"dexterity":14,"constitution":16,"intelligence":14,"wisdom":15,"charisma":24,"baseatk":16,"cmb":21,"cmd":31,"feats":[{"feat":"Arcane Strike"},{"feat":"Blinding Critical"},{"feat":"Brew Potion"},{"feat":"Combat Casting"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Deceitful"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (claw)"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Silent Spell"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":37},{"skill":"Craft (alchemy)","value":24},{"skill":"Disguise","value":17},{"skill":"Fly","value":13},{"skill":"Heal","value":20},{"skill":"Knowledge (arcana)","value":19},{"skill":"Knowledge (local)","value":9},{"skill":"Knowledge (planes)","value":21},{"skill":"Linguistics","value":5},{"skill":"Spellcraft","value":21},{"skill":"Swim","value":13}],"languages":["Common","Aklo","Giant","Infernal","Sylvan","Undercommon"],"sq":["bloodline arcana","mimicry"],"gear":"headband of alluring charisma +2, ring of protection +2, staff of swarming insects (10 charges)","before_combat":"The mother of flies casts mage armor and nondetection on herself every morning and every evening. Before entering combat, she always takes the time to also cast cat's grace, fly, and shield.","during_combat":"The Mother of Flies directs any swarms available to her to distract foes while she tries to remain out of range with flight, using her spells against foes. She'll retreat to the Maggot Tree core to use the tree's attacks against attackers if possible. In melee, she uses Arcane Strike, Power Attack, and usually Vital Strike to maximize damage while allowing her to move out of melee after each attack.","morale":"The Mother of Flies uses teleport to flee to the Court of Ether if reduced to fewer than 40 hit points, but harbors a grudge if she's forced to do so. She might even throw aside her hatred of the Council of Thieves if the PCs force her to flee in this manner, and could show up in the final adventure as an additional foe in this case.","base_statistics":"Init +0; AC 20, touch 12, flat-footed 20; Ref +10; Dex 14; Skills Fly +11","source":"AP 29, Pathfinder RPG Bestiary 167"},{"name":"Shadow Mastiff","cr":5,"xp":1600,"race":"Shadow Mastiff","age_category":"Adult","alignment":"NE","size":"Medium","type":"outsider","sub_types":["evil","extraplanar"],"init":6,"senses":["darkvision 60 ft.","scent"],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":51,"hd":"6d10+18","hd_value":6,"fort":8,"ref":7,"will":5,"defensive_abilities":["shadow blend"],"speed":[{"type":"land","speed":50}],"melee":"bite +10 (1d6+6 plus trip)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bay"}],"strength":19,"dexterity":15,"constitution":17,"intelligence":4,"wisdom":12,"charisma":13,"baseatk":6,"cmb":10,"cmd":22,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":11},{"skill":"Survival","value":10}],"languages":["Common (cannot speak)"],"special_abilities":[{"type":"Bay","kind":"Su","details":"When a shadow mastiff howls or barks, all creatures except evil outsiders within a 300-foot spread must succeed on a DC 16 Will save or become panicked for 2d4 rounds. This is a sonic, mind-affecting fear effect. A creature that successfully saves cannot be affected by the same mastiff's bay for 24 hours. The save DC is Charisma-based and includes a +2 racial bonus."},{"type":"Shadow Blend","kind":"Su","details":"In any condition other than bright light, a shadow mastiff disappears into the shadows, giving it total concealment (50% miss chance). A shadow mastiff can suspend or resume this ability as a free action."}],"during_combat":"A shadow mastiff uses its bay attack throughout combat, alerting most of the other denizens of Walcourt that something has blundered into the grounds. They generally focus their attacks on any foe that carries a light source.","morale":"Shadow mastiffs fight to the death.","source":"AP 29, Bonus Bestiary 16"},{"name":"Novice Thief","cr":1,"xp":400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":2}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 armor, +2 Dex","hp":15,"hd":"2d8+6","hd_value":2,"fort":2,"ref":5,"will":-1,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":30}],"melee":"mwk rapier +3 (1d6+1/18-20)","ranged":"hand crossbow +3 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":13,"dexterity":15,"constitution":14,"intelligence":12,"wisdom":8,"charisma":10,"baseatk":1,"cmb":2,"cmd":14,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Appraise","value":6},{"skill":"Bluff","value":5},{"skill":"Climb","value":5},{"skill":"Disable Device","value":6},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":4},{"skill":"Sense Motive","value":4},{"skill":"Sleight of Hand","value":7},{"skill":"Stealth","value":6}],"languages":["Common","Infernal"],"sq":["rogue talent (finesse rogue)","trapfinding"],"gear":"studded leather, masterwork rapier, hand crossbow with 20 bolts, 25 gp","during_combat":"Confronted here in relatively tight quarters, half the rogues take a stand against the PCs while the others flee through the secret doors through area C7 to try to come around and flank the enemy.","morale":"Eager to please their new masters, these novices fight to the death.","source":"AP 29"},{"name":"Shadow Rat Swarm","cr":4,"xp":1200,"race":"Shadow Rat Swarm","age_category":"Adult","alignment":"NE","size":"Tiny","type":"undead","sub_types":["swarm"],"init":6,"senses":["darkvision 60 ft.","scent"],"ac":15,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 natural, +2 size","hp":39,"hd":"6d8+12","hd_value":6,"fort":4,"ref":6,"will":6,"defensive_abilities":["half damage from piercing and slashing","incorporeal form","shadow blend"],"immunities":["swarm traits","undead traits"],"weaknesses":["swarm traits"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":40}],"melee":"swarm +4 (2d6-2 plus 1d4 Str and distraction)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 15"}],"strength":6,"dexterity":15,"intelligence":2,"wisdom":12,"charisma":14,"baseatk":4,"cmb":4,"cmd":12,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":4,"special":"+4 jump"},{"skill":"Climb","value":10},{"skill":"Fly","value":0},{"skill":"Perception","value":9},{"skill":"Stealth","value":19}],"special_abilities":[{"type":"Incorporeal Form","kind":"Su","details":"A shadow rat swarm can, as a standard action, assume an incorporeal form for up to 1 hour per day. In this form, the swarm loses its natural AC bonus but gains a +2 deflection bonus to AC. While in this form, the shadow rat swarm is AC 16 (+2 deflection, +2 Dex, +2 size), touch 15, flat-footed 13. The shadow rat swarm can still swarm attack corporeal opponents while in its incorporeal form, but its attack only inflicts Strength damage and cannot distract foes or cause physical damage. The shadow rat swarm gains the incorporeal subtype while using this ability."},{"type":"Shadow Blend","kind":"Ex","details":"A shadow rat swarm can disappear into the shadows as a move action, gaining total concealment in all levels of illumination save bright light."},{"type":"Strength Drain","kind":"Su","details":"A shadow rat swarm deals Strength damage to living foes over which it swarms. A creature reduced to 0 Strength cannot move but doesn't die-at least, not until the swarm's physical damage takes its toll."}],"during_combat":"The rats attack the closest target, preferring to attack foes that carry light sources.","morale":"The swarm fights until destroyed.","source":"AP 29, Tome of Horrors III 184"},{"name":"Sandor the Strange","cr":11,"xp":12800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"diviner","level":12}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":12,"senses":["arcane sight","darkvision 60 ft.","prying eyes","see invisibility","true seeing"],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+2 armor, +2 Dex, +1 dodge, +4 shield","hp":81,"hd":"12d6+39","hd_value":12,"fort":7,"ref":6,"will":9,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 quarterstaff +7 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"diviner's fortune","details":"+6, 9/day"}],"spellsprepared_caster":"wizard","spellsprepared_caster_level":12,"spellsprepared_concentration":18,"spellsprepared":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"disintegrate"},{"spell":"forceful hand"},{"spell":"mislead"},{"spell":"true seeing"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"cone of cold"},{"spell":"false vision"},{"spell":"overland flight"},{"spell":"passwall"},{"spell":"prying eyes"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"enervation"},{"spell":"greater invisibility"},{"spell":"locate creature"},{"spell":"phantasmal killer"},{"spell":"scrying"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"clairaudience/ clairvoyance"},{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"slow"},{"spell":"vampiric touch","count":2}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"arcane lock"},{"spell":"darkness"},{"spell":"detect thoughts"},{"spell":"false life"},{"spell":"protection from arrows"},{"spell":"scorching ray","count":2}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"comprehend languages"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"ray of enfeeblement"},{"spell":"shield"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"read magic"}]}],"prohibited_schools":"Conjuration, Enchantment","strength":10,"dexterity":14,"constitution":13,"intelligence":22,"wisdom":12,"charisma":8,"baseatk":6,"cmb":6,"cmd":19,"feats":[{"feat":"Combat Casting"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Magical Aptitude"},{"feat":"Mobility"},{"feat":"Scribe Scroll"}],"skills":[{"skill":"Appraise","value":21},{"skill":"Craft (Trapmaking)","value":21},{"skill":"Fly","value":12},{"skill":"Knowledge (arcana)","value":21},{"skill":"Knowledge (history)","value":21},{"skill":"Knowledge (local)","value":21},{"skill":"Perception","value":13},{"skill":"Spellcraft","value":25},{"skill":"Use Magic Device","value":15}],"languages":["Common","Aklo","Azlanti","Infernal","Shadowtongue","Varisian"],"sq":["arcane bond (staff)","contingency","forewarned","permanent spells","scrying adept"],"special_abilities":[{"type":"Contingency","details":"If Sandor takes damage, a stoneskin spell activates on him. Permanent Spells Sandor has made the following spells permanent on himself: arcane sight, darkvision, and see invisibility. Staff of the Blue Dragon This +1 quarterstaff is Sandor's arcane bonded object. The staff of the blue dragon allows Sandor the use of the following spells: ventriloquism (1 charge), lightning bolt (2 charges), and fear (4 charges)."}],"gear":"staff of the blue dragon, bracers of armor +2, headband of vast intelligence +2 (Use Magic Device), key, scroll of shadow walk","before_combat":"Sandor typically casts false life, prying eyes, overland flight, and protection from arrows on himself each day, and all are in effect when the PCs arrive. Assuming that the PCs are spotted by his prying eyes, he casts the following spells to prepare for their arrival: greater invisibility, protection from good, true seeing, and shield. He then hovers invisibly near the ceiling in the garret chamber, awaiting the necessity of defending his home.","during_combat":"When the PCs enter, Sandor uses flight and invisibility to position himself before he begins hitting the party with lightning bolts and fear from his staff, then switches to ranged spells like disintegrate, cone of cold, phantasmal killer and others.","morale":"If badly wounded, Sandor casts mislead, ducks into a nearby room, then uses his scroll of shadow walk and seeks out Chammady and Ecarrdian-if he does so, he can appear in the next adventure as an additional enemy, but his report to the Drovenges doesn't encourage them to increase protection at Walcourt. They assume that Ilnerik has things well in hand, and neither is aware that there's something hidden in the treasury below that could undo their devotion to each other.","base_statistics":"AC 15, touch 13, flat-footed 12; hp 66","source":"AP 29"}];
